// Generated by `dart run live_timer_widget:setup_ios`. It's yours now: edit
// the look freely, and run setup_ios with --force to start over.
//
// The widget reads only what `LiveTimerWidget` (Dart) writes into the App
// Group, and shows it without the app: the clock is `Text(_, style: .timer)`,
// which iOS ticks every second, and a timeline of entries moves the progress,
// stages and completion on time.
//
// The rules (`Snapshot.resolve`) mirror lib/src/snapshot.dart in the plugin.

import SwiftUI
import WidgetKit

private let appGroupId = "group.io.github.abdoshamss.liveTimerWidgetExample"
private let widgetKind = "LiveTimerWidget"
private let displayName = "Live Timer"
private let widgetDescription = "A live timer that keeps running with the app closed."

/// Shown before the app first writes its idle content.
private let defaultIdleTitle = "No timer running"
private let defaultIdleSubtitle = "Open the app to start one"

// Shared with the plugin's LiveTimerWidgetPlugin.swift.
private let stateKey = "live_timer_widget.state"
private let imagesDir = "live_timer_widget"
private let tapScheme = "livetimerwidget"

// MARK: - Stored state

struct StageSpec: Decodable {
  var afterMs: Double?
  var progress: Double?
  var title: String?
  var subtitle: String?
  var image: String?
  var accent: UInt32?
}

struct TimerSpec: Decodable {
  var startMs: Double
  var endMs: Double?
  var direction: String?
  var completion: String?
  var maxMs: Double?
  var title: String?
  var subtitle: String?
  var completedTitle: String?
  var completedSubtitle: String?
  var image: String?
  var accent: UInt32?
  var showProgress: Bool?
  var link: String?
  var stages: [StageSpec]?

  var start: Date { Date(timeIntervalSince1970: startMs / 1000) }
  var end: Date? { endMs.map { Date(timeIntervalSince1970: $0 / 1000) } }
  var countsDown: Bool { direction == "down" }
  var goal: TimeInterval? { end.map { $0.timeIntervalSince(start) } }

  /// Seconds after the start [stage] is reached; nil if never.
  func offset(of stage: StageSpec) -> TimeInterval? {
    if let after = stage.afterMs { return after / 1000 }
    guard let progress = stage.progress else { return nil }
    if progress == 0 { return 0 }
    guard let goal, goal > 0 else { return nil }
    return goal * progress
  }
}

struct IdleSpec: Decodable {
  var title: String?
  var subtitle: String?
  var actionLabel: String?
  var image: String?
  var link: String?
  var actionLink: String?
}

struct StyleSpec: Decodable {
  var background: UInt32 = 0xFF1B_1530
  var backgroundEnd: UInt32?
  var foreground: UInt32 = 0xFFFF_FFFF
  var muted: UInt32 = 0xCCFF_FFFF
  var accent: UInt32 = 0xFF8A_C443
  var onAccent: UInt32 = 0xFF14_101F
  var track: UInt32 = 0x38FF_FFFF
  var imageScrim: Bool = true

  init() {}

  init(from decoder: Decoder) throws {
    let c = try decoder.container(keyedBy: CodingKeys.self)
    let d = StyleSpec()
    background = try c.decodeIfPresent(UInt32.self, forKey: .background) ?? d.background
    backgroundEnd = try c.decodeIfPresent(UInt32.self, forKey: .backgroundEnd)
    foreground = try c.decodeIfPresent(UInt32.self, forKey: .foreground) ?? d.foreground
    muted = try c.decodeIfPresent(UInt32.self, forKey: .muted) ?? d.muted
    accent = try c.decodeIfPresent(UInt32.self, forKey: .accent) ?? d.accent
    onAccent = try c.decodeIfPresent(UInt32.self, forKey: .onAccent) ?? d.onAccent
    track = try c.decodeIfPresent(UInt32.self, forKey: .track) ?? d.track
    imageScrim = try c.decodeIfPresent(Bool.self, forKey: .imageScrim) ?? d.imageScrim
  }

  private enum CodingKeys: String, CodingKey {
    case background, backgroundEnd, foreground, muted, accent, onAccent, track, imageScrim
  }
}

struct WidgetState: Decodable {
  var rtl: Bool?
  var style: StyleSpec?
  var idle: IdleSpec?
  var timer: TimerSpec?

  static func load() -> WidgetState {
    guard let raw = UserDefaults(suiteName: appGroupId)?.string(forKey: stateKey),
      let data = raw.data(using: .utf8),
      let state = try? JSONDecoder().decode(WidgetState.self, from: data)
    else { return WidgetState() }
    return state
  }

  static func imagePath(_ name: String?) -> String? {
    guard let name, !name.isEmpty,
      let container = FileManager.default.containerURL(
        forSecurityApplicationGroupIdentifier: appGroupId)
    else { return nil }
    return container.appendingPathComponent(imagesDir).appendingPathComponent(name).path
  }
}

// MARK: - Rules

enum Phase { case idle, running, completed }

struct Snapshot {
  var phase: Phase = .idle
  var progress: Double?
  var stage: StageSpec?
  /// Counting up from / down to this instant, when ticking.
  var clockAnchor: Date?
  var countsDown = false
  /// Shown instead of a ticking clock (`TimerCompletion.freeze`).
  var frozen: TimeInterval?
  var title = ""
  var subtitle: String?

  static func resolve(_ timer: TimerSpec?, at now: Date) -> Snapshot {
    guard let timer else { return Snapshot() }
    let elapsed = now.timeIntervalSince(timer.start)
    if let max = timer.maxMs, elapsed >= max / 1000 { return Snapshot() }

    let end = timer.end
    let completed = end.map { now >= $0 } ?? false
    if completed, timer.completion == "idle" { return Snapshot() }

    var progress: Double?
    if let goal = timer.goal {
      progress = goal <= 0 ? 1 : min(max(elapsed / goal, 0), 1)
    }

    let stage = stage(of: timer, elapsed: elapsed)
    let percent = progress.map { "\(Int(($0 * 100).rounded(.down)))%" } ?? ""
    func fill(_ text: String) -> String { text.replacingOccurrences(of: "{percent}", with: percent) }

    let title = (completed ? timer.completedTitle : nil) ?? stage?.title ?? timer.title ?? ""
    let subtitle = (completed ? timer.completedSubtitle : nil) ?? stage?.subtitle ?? timer.subtitle

    var snapshot = Snapshot(
      phase: completed ? .completed : .running, progress: progress, stage: stage,
      title: fill(title), subtitle: subtitle.map(fill))
    if !completed {
      snapshot.countsDown = timer.countsDown
      snapshot.clockAnchor = timer.countsDown ? end : timer.start
    } else if timer.completion == "freeze" {
      snapshot.frozen = timer.countsDown ? 0 : timer.goal
    } else {
      // keepCounting: a countdown becomes overtime since the end.
      snapshot.clockAnchor = timer.countsDown ? end : timer.start
    }
    return snapshot
  }

  /// Every instant after [now] at which `resolve` changes phase or stage.
  static func changes(of timer: TimerSpec, after now: Date) -> [Date] {
    var dates: [Date] = []
    if let end = timer.end { dates.append(end) }
    if let max = timer.maxMs { dates.append(timer.start.addingTimeInterval(max / 1000)) }
    for stage in timer.stages ?? [] {
      if let offset = timer.offset(of: stage) { dates.append(timer.start.addingTimeInterval(offset)) }
    }
    return dates.filter { $0 > now }
  }

  private static func stage(of timer: TimerSpec, elapsed: TimeInterval) -> StageSpec? {
    var match: StageSpec?
    var best: TimeInterval?
    for stage in timer.stages ?? [] {
      guard let offset = timer.offset(of: stage), offset <= elapsed else { continue }
      // Later in the list wins a tie.
      if best == nil || offset >= best! {
        best = offset
        match = stage
      }
    }
    return match
  }
}

// MARK: - Timeline

struct LiveTimerEntry: TimelineEntry {
  let date: Date
  let state: WidgetState
  let snapshot: Snapshot
}

struct LiveTimerProvider: TimelineProvider {
  func placeholder(in context: Context) -> LiveTimerEntry { entry(at: Date(), WidgetState.load()) }

  func getSnapshot(in context: Context, completion: @escaping (LiveTimerEntry) -> Void) {
    completion(entry(at: Date(), WidgetState.load()))
  }

  /// An entry at every phase or stage change, plus one per ~half percent of
  /// progress (1–15 min apart), so the bar and `{percent}` move on their own.
  func getTimeline(in context: Context, completion: @escaping (Timeline<LiveTimerEntry>) -> Void) {
    let state = WidgetState.load()
    let now = Date()
    var dates = [now]
    var policy = TimelineReloadPolicy.never
    if let timer = state.timer, Snapshot.resolve(timer, at: now).phase != .idle {
      dates += Snapshot.changes(of: timer, after: now)
      if let goal = timer.goal, goal > 0, let end = timer.end, end > now {
        let step = min(max(goal / 200, 60), 15 * 60)
        var next = now.addingTimeInterval(step)
        while next < end, dates.count < 120 {
          dates.append(next)
          next = next.addingTimeInterval(step)
        }
        // Ask for more if the steps ran out before the end.
        if next < end { policy = .after(next) }
      }
    }
    let entries = Set(dates).sorted().map { entry(at: $0, state) }
    completion(Timeline(entries: entries, policy: policy))
  }

  private func entry(at date: Date, _ state: WidgetState) -> LiveTimerEntry {
    LiveTimerEntry(date: date, state: state, snapshot: Snapshot.resolve(state.timer, at: date))
  }
}

// MARK: - Views

extension Color {
  init(argb: UInt32) {
    self.init(
      .sRGB,
      red: Double((argb >> 16) & 0xFF) / 255,
      green: Double((argb >> 8) & 0xFF) / 255,
      blue: Double(argb & 0xFF) / 255,
      opacity: Double((argb >> 24) & 0xFF) / 255)
  }
}

struct LiveTimerWidgetView: View {
  @Environment(\.widgetFamily) private var family
  let entry: LiveTimerEntry

  private var state: WidgetState { entry.state }
  private var snapshot: Snapshot { entry.snapshot }
  private var style: StyleSpec { state.style ?? StyleSpec() }
  private var running: Bool { snapshot.phase != .idle }
  private var compact: Bool { family == .systemSmall }

  private var accent: Color {
    Color(argb: snapshot.stage?.accent ?? (running ? state.timer?.accent : nil) ?? style.accent)
  }

  private var isLockScreen: Bool {
    switch family {
    case .systemSmall, .systemMedium, .systemLarge, .systemExtraLarge: return false
    default: return true
    }
  }

  var body: some View {
    Group {
      if #available(iOS 16.0, *), isLockScreen {
        lockScreen.lockScreenBackground()
      } else {
        home.widgetBackground { backdrop }
      }
    }
    .environment(\.layoutDirection, layoutDirection)
    .widgetURL(tapURL(link: running ? state.timer?.link : state.idle?.link, target: "widget"))
  }

  private var layoutDirection: LayoutDirection {
    if let rtl = state.rtl { return rtl ? .rightToLeft : .leftToRight }
    let language = Locale.current.languageCode ?? "en"
    return Locale.characterDirection(forLanguage: language) == .rightToLeft
      ? .rightToLeft : .leftToRight
  }

  // Home screen

  @ViewBuilder private var home: some View {
    if running {
      VStack(alignment: .leading, spacing: 0) {
        HStack(spacing: 6) {
          Circle().fill(accent).frame(width: 7, height: 7)
          Text(snapshot.title).font(.caption2.bold()).lineLimit(1)
            .foregroundColor(Color(argb: style.foreground))
          Spacer(minLength: 4)
          if let progress = snapshot.progress {
            Text("\(Int((progress * 100).rounded(.down)))%")
              .font(.caption2.bold()).foregroundColor(accent)
          }
        }
        Spacer(minLength: 4)
        clock
          .font(.system(size: compact ? 26 : 34, weight: .bold, design: .rounded))
          .monospacedDigit().lineLimit(1).minimumScaleFactor(0.6)
          .foregroundColor(Color(argb: style.foreground))
        if !compact, let subtitle = snapshot.subtitle, !subtitle.isEmpty {
          Text(subtitle).font(.caption).lineLimit(1)
            .foregroundColor(Color(argb: style.muted))
            .padding(.top, 2)
        }
        if state.timer?.showProgress ?? true, let progress = snapshot.progress {
          ProgressBar(progress: progress, fill: accent, track: Color(argb: style.track))
            .frame(height: 6).padding(.top, 10)
        }
      }
      .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
    } else {
      VStack(alignment: .leading, spacing: 0) {
        Spacer(minLength: 0)
        Text(state.idle?.title ?? defaultIdleTitle)
          .font(.system(size: compact ? 17 : 21, weight: .bold, design: .rounded))
          .lineLimit(2).minimumScaleFactor(0.7)
          .foregroundColor(Color(argb: style.foreground))
        let subtitle = state.idle == nil ? defaultIdleSubtitle : state.idle?.subtitle
        if !compact, let subtitle, !subtitle.isEmpty {
          Text(subtitle).font(.caption).lineLimit(2)
            .foregroundColor(Color(argb: style.muted))
            .padding(.top, 4)
        }
        if let label = state.idle?.actionLabel, !label.isEmpty {
          actionButton(label).padding(.top, 12)
        }
        Spacer(minLength: 0)
      }
      .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .leading)
    }
  }

  @ViewBuilder private var clock: some View {
    if let frozen = snapshot.frozen {
      Text(Self.format(frozen))
    } else if let anchor = snapshot.clockAnchor {
      // Counts down to a future anchor, up from a past one.
      Text(anchor, style: .timer)
    }
  }

  /// A small widget is one tap target, so its button is only decoration.
  @ViewBuilder private func actionButton(_ label: String) -> some View {
    let button = HStack(spacing: 6) {
      Image(systemName: "play.fill").font(.caption2.bold())
      Text(label).font(.footnote.bold()).lineLimit(1)
    }
    .foregroundColor(Color(argb: style.onAccent))
    .padding(.horizontal, 16).padding(.vertical, 8)
    .background(Capsule().fill(accent))

    if !compact, let url = tapURL(link: state.idle?.actionLink ?? state.idle?.link, target: "action") {
      Link(destination: url) { button }
    } else {
      button
    }
  }

  private var backdrop: some View {
    let image = (running ? snapshot.stage?.image ?? state.timer?.image : state.idle?.image)
      .flatMap(WidgetState.imagePath)
      .flatMap(UIImage.init(contentsOfFile:))
    let base = Color(argb: style.background)
    return ZStack {
      LinearGradient(
        colors: [base, Color(argb: style.backgroundEnd ?? style.background)],
        startPoint: .topLeading, endPoint: .bottomTrailing)
      if let image {
        Image(uiImage: image).resizable().scaledToFill()
        if style.imageScrim {
          LinearGradient(
            stops: [
              .init(color: base.opacity(0.95), location: 0),
              .init(color: base.opacity(0.7), location: 0.5),
              .init(color: base.opacity(0.1), location: 1),
            ],
            startPoint: .leading, endPoint: .trailing)
          LinearGradient(colors: [base.opacity(0.6), .clear], startPoint: .bottom, endPoint: .center)
        }
      }
    }
  }

  // Lock screen

  @available(iOS 16.0, *)
  @ViewBuilder private var lockScreen: some View {
    switch family {
    case .accessoryCircular:
      if running, let progress = snapshot.progress {
        Gauge(value: progress) { EmptyView() } currentValueLabel: {
          Text("\(Int((progress * 100).rounded(.down)))")
        }
        .gaugeStyle(.accessoryCircularCapacity)
      } else if running {
        ZStack {
          AccessoryWidgetBackground()
          clock.font(.caption2.bold()).monospacedDigit().minimumScaleFactor(0.5)
            .multilineTextAlignment(.center).padding(4)
        }
      } else {
        ZStack {
          AccessoryWidgetBackground()
          Image(systemName: "timer")
        }
      }
    case .accessoryInline:
      if running {
        clock
      } else {
        Text(state.idle?.title ?? defaultIdleTitle)
      }
    default:
      if running {
        VStack(alignment: .leading, spacing: 2) {
          Text(snapshot.title).font(.caption2).lineLimit(1)
          clock.font(.headline).monospacedDigit().lineLimit(1)
          if state.timer?.showProgress ?? true, let progress = snapshot.progress {
            ProgressBar(progress: progress, fill: .primary, track: .primary.opacity(0.25))
              .frame(height: 4)
          }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
      } else {
        Text(state.idle?.title ?? defaultIdleTitle).font(.headline).lineLimit(2)
      }
    }
  }

  private func tapURL(link: String?, target: String) -> URL? {
    var components = URLComponents()
    components.scheme = tapScheme
    components.host = "tap"
    components.queryItems = [
      URLQueryItem(name: "target", value: target),
      URLQueryItem(name: "link", value: link ?? ""),
    ]
    return components.url
  }

  /// `1:02:03` / `02:03`, like `Text(_, style: .timer)`.
  static func format(_ interval: TimeInterval?) -> String {
    let total = Int(max(interval ?? 0, 0))
    let (h, m, s) = (total / 3600, total / 60 % 60, total % 60)
    return h > 0
      ? String(format: "%d:%02d:%02d", h, m, s)
      : String(format: "%02d:%02d", m, s)
  }
}

/// Grows from the leading edge, so it follows the layout direction.
private struct ProgressBar: View {
  let progress: Double
  let fill: Color
  let track: Color

  var body: some View {
    GeometryReader { proxy in
      ZStack(alignment: .leading) {
        Capsule().fill(track)
        Capsule().fill(fill)
          .frame(width: max(proxy.size.height, proxy.size.width * progress))
          .opacity(progress > 0 ? 1 : 0)
      }
    }
  }
}

extension View {
  /// iOS 17 wants the background declared as the container's, and adds the
  /// content margins itself.
  @ViewBuilder func widgetBackground<B: View>(@ViewBuilder _ background: () -> B) -> some View {
    if #available(iOS 17.0, *) {
      containerBackground(for: .widget, content: background)
    } else {
      padding(16).background(background())
    }
  }

  @ViewBuilder func lockScreenBackground() -> some View {
    if #available(iOS 17.0, *) {
      containerBackground(for: .widget) { Color.clear }
    } else {
      self
    }
  }
}

// MARK: - Widget

@main
struct LiveTimerWidget: Widget {
  private var families: [WidgetFamily] {
    if #available(iOS 16.0, *) {
      return [
        .systemSmall, .systemMedium, .accessoryRectangular, .accessoryCircular, .accessoryInline,
      ]
    }
    return [.systemSmall, .systemMedium]
  }

  var body: some WidgetConfiguration {
    StaticConfiguration(kind: widgetKind, provider: LiveTimerProvider()) {
      LiveTimerWidgetView(entry: $0)
    }
    .configurationDisplayName(displayName)
    .description(widgetDescription)
    .supportedFamilies(families)
  }
}
